 12 │ // ─── Session store ────────────────────────────────────────────────────────────
 13 │ 
 14 │ static SESSIONS: LazyLock<DashMap<u32, Arc<WatchSession>>> = LazyLock::new(DashMap::new);
 15 │ static NEXT_SESSION_ID: AtomicU64 = AtomicU64::new(0);
 16 │ 
 17 │ /// Src-dir value that trips a simulated panic inside `create_session`'s real
 18 │ /// body — exists only to let tests exercise `panic_guard::contain_panic`'s
 19 │ /// containment through the actual production entry point, the same pattern
 20 │ /// `oxc_react_docgen_core::pipeline`'s `PARSE_PANIC_TEST_SENTINEL` uses.
 21 │ #[cfg(test)]
 22 │ const CREATE_SESSION_PANIC_TEST_SENTINEL: &str = "__CREATE_SESSION_PANIC_TEST__";
 23 │ 
 24 │ /// Src-dir value that trips a simulated panic inside `extract_all`'s real
 25 │ /// body (at the `pipeline::extract` step, before serialization). SPEC-BINDING-001 AC6.
 26 │ #[cfg(test)]
 27 │ const EXTRACT_ALL_PANIC_TEST_SENTINEL: &str = "__EXTRACT_ALL_PANIC_TEST__";
 28 │ 
 29 │ /// Reserved `session_id` values used only by `#[cfg(test)]` sentinel checks
 30 │ /// below, to trip a simulated panic at a SPECIFIC point in each entry
 31 │ /// point's real body. Each targets a different point deliberately — see
 32 │ /// SPEC-BINDING-001 AC3/AC7/AC8/AC10, which each require proving panic
 33 │ /// containment at a *distinct* trigger site, not just "some panic somewhere
 34 │ /// is caught":
 35 │ ///
 36 │ /// - `AUTO_VIVIFY_PANIC_TEST_SENTINEL` fires during auto-vivified
 37 │ ///   `WatchSession` construction (the `None` branch of the SESSIONS.get
 38 │ ///   match in `initialize_session`/`extract_file_incremental`) — before the
 39 │ ///   session is registered at all.
 40 │ /// - `INITIALIZE_SESSION_PANIC_TEST_SENTINEL` fires at `initialize_session`'s
 41 │ ///   actual core call (`session.initialize()`), reachable only for an
 42 │ ///   ALREADY-REGISTERED session — i.e. strictly after auto-vivification (or
 43 │ ///   `create_session`) has already completed. Distinct from
 44 │ ///   `AUTO_VIVIFY_PANIC_TEST_SENTINEL`'s trigger point.
 45 │ /// - `CLOSE_SESSION_PANIC_TEST_SENTINEL` fires inside `close_session`'s body.
 46 │ ///
 47 │ /// Chosen as the top of `u32`'s range: `next_session_id()`'s output is
 48 │ /// `(pid & 0xFFFF) << 16 | (counter & 0xFFFF)`, so either value could
 49 │ /// theoretically collide with a real generated ID under an astronomically
 50 │ /// unlikely combination of process ID and call count — judged an acceptable
 51 │ /// risk for test-only sentinels, consistent with the documented tradeoff on
 52 │ /// `next_session_id`'s own 16-bit allocation.
 53 │ #[cfg(test)]
 54 │ const AUTO_VIVIFY_PANIC_TEST_SENTINEL: u32 = u32::MAX;
 55 │ #[cfg(test)]
 56 │ const INITIALIZE_SESSION_PANIC_TEST_SENTINEL: u32 = u32::MAX - 1;
 57 │ #[cfg(test)]
 58 │ const CLOSE_SESSION_PANIC_TEST_SENTINEL: u32 = u32::MAX - 3;
 59 │ 
 60 │ /// `extract_file_incremental`'s core-call sentinel is file_path-based
 61 │ /// instead — its core call (`session.update_file(path)`) is keyed by path,
 62 │ /// not session_id, so a distinguishing file_path is the natural trigger for
 63 │ /// SPEC-BINDING-001 AC8, reached only for an already-registered session,
 64 │ /// strictly after `AUTO_VIVIFY_PANIC_TEST_SENTINEL`'s trigger point.
 65 │ #[cfg(test)]
 66 │ const EXTRACT_FILE_INCREMENTAL_PANIC_TEST_SENTINEL: &str = "__EXTRACT_FILE_INCREMENTAL_PANIC_TEST__";
 67 │ 
 68 │ /// Pure bit-packing seam for `next_session_id()`, so SPEC-BINDING-001 AC4's
 69 │ /// uniqueness claim (no duplicate for N <= 65,536 calls in one process) is
 70 │ /// testable directly against synthetic counter values — `next_session_id()`
 71 │ /// itself reads a real, process-global `AtomicU64` shared across every test
 72 │ /// in this binary (including other tests' own `next_session_id()`/
 73 │ /// `create_session()` calls), so driving 65,536 real calls through it would
 74 │ /// risk wrapping mid-test on however much prior pollution happened to land
 75 │ /// before this test ran, under parallel test execution.
 76 │ fn compute_session_id(pid: u64, counter: u64) -> u32 {
 77 │     // Avoids session-ID collisions across concurrent Vite dev server instances.
 78 │     (((pid & 0xFFFF) << 16) | (counter & 0xFFFF)) as u32
 79 │ }
 80 │ 
 81 │ fn next_session_id() -> u32 {
 82 │     let pid = std::process::id() as u64;
 83 │     let counter = NEXT_SESSION_ID.fetch_add(1, Ordering::Relaxed);
 84 │     compute_session_id(pid, counter)
 85 │ }
