113 │ // ─── TryFrom<JsExtractOptions> for PipelineOptions ────────────────────────────
114 │ 
115 │ impl TryFrom<JsExtractOptions> for PipelineOptions {
116 │     /// Names the bad `reactVersion` value — a typo (or a caller bypassing the
117 │     /// `'react18' | 'react19'` TS type, e.g. via `as any`) must not silently
118 │     /// fall back to react19 (CLAUDE.md non-negotiable #6).
119 │     type Error = String;
120 │ 
121 │     fn try_from(js: JsExtractOptions) -> Result<Self, Self::Error> {
122 │         use compact_str::CompactString;
123 │ 
124 │         let mut opts =
125 │             PipelineOptions { src_dirs: js.src_dirs.into_iter().map(Into::into).collect(), ..Default::default() };
126 │ 
127 │         if let Some(exclude) = js.exclude {
128 │             opts.exclude_patterns = exclude;
129 │         }
130 │         if let Some(v) = js.react_version.as_deref() {
131 │             opts.react_version = oxc_react_docgen_core::react_types::parse_react_version(v)
132 │                 .map_err(|bad| format!("reactVersion is '{bad}', expected \"react18\" or \"react19\""))?;
133 │         }
134 │         if let Some(cross_package) = js.cross_package {
135 │             opts.cross_package = cross_package;
136 │         }
137 │         if let Some(dir) = js.pandacss_outdir {
138 │             opts.pandacss_outdir = Some(dir.into());
139 │         }
140 │         if let Some(fns) = js.variant_functions {
141 │             opts.variant_functions = fns;
142 │         }
143 │         if let Some(mode) = js.html_attributes.as_deref() {
144 │             opts.html_attributes = match mode {
145 │                 "full" => oxc_react_docgen_core::pipeline::HtmlAttributeMode::Full,
146 │                 "none" => oxc_react_docgen_core::pipeline::HtmlAttributeMode::None,
147 │                 _ => oxc_react_docgen_core::pipeline::HtmlAttributeMode::Curated,
148 │             };
149 │         }
150 │         if let Some(path) = js.tsconfig_path {
151 │             opts.tsconfig_path = Some(path.into());
152 │         }
153 │         if let Some(names) = js.extra_builtins {
154 │             opts.extra_builtins = names.into_iter().map(CompactString::from).collect();
155 │         }
156 │         if let Some(json) = js.extra_paths_json {
157 │             opts.extra_paths = serde_json::from_str(&json).map_err(|e| format!("extraPaths is not valid JSON: {e}"))?;
158 │         }
159 │         if let Some(json) = js.known_type_overrides_json {
160 │             opts.known_type_overrides =
161 │                 serde_json::from_str(&json).map_err(|e| format!("knownTypeOverrides is not valid JSON: {e}"))?;
162 │         }
163 │         if let Some(v) = js.vanilla_extract {
164 │             opts.vanilla_extract = v;
165 │         }
166 │         if let Some(dir) = js.cache_dir {
167 │             opts.cache_dir = Some(dir.into());
168 │         }
169 │         if let Some(v) = js.resolve_complex_types {
170 │             opts.resolve_complex_types = v;
171 │         }
172 │ 
173 │         Ok(opts)
174 │     }
175 │ }
