179 │ /// Cold extraction — returns JSON string of ExtractionOutput.
180 │ /// Use for: build-time extraction, CLI backing, one-off runs.
181 │ #[napi]
182 │ pub async fn extract_all(options: JsExtractOptions) -> napi::Result<String> {
183 │     let pipeline_options = PipelineOptions::try_from(options).map_err(napi::Error::from_reason)?;
184 │     tokio::task::spawn_blocking(move || {
185 │         match oxc_react_docgen_core::panic_guard::contain_panic("extract_all", move || {
186 │             #[cfg(test)]
187 │             if pipeline_options.src_dirs.iter().any(|d| d.as_str() == EXTRACT_ALL_PANIC_TEST_SENTINEL) {
188 │                 panic!("simulated extract_all panic (test-only sentinel)");
189 │             }
190 │ 
191 │             let output = oxc_react_docgen_core::pipeline::extract(&pipeline_options);
192 │             extraction_output_to_json(&output).map_err(|e| napi::Error::from_reason(e.to_string()))
193 │         }) {
194 │             Ok(result) => result,
195 │             Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
196 │         }
197 │     })
198 │     .await
199 │     .map_err(|e| napi::Error::from_reason(e.to_string()))?
200 │ }
