   1 //! Single sanctioned panic-containment boundary (see ADR 0005).
   2 //!
   3 //! Every panic reachable from a rayon `.map()`, a `DocgenPlugin` hook, or a
   4 //! NAPI entry point crosses this function on its way to becoming a
   5 //! `Diagnostic` instead of aborting a batch, killing the whole pipeline, or
   6 //! poisoning a session lock.
   7 
   8 use crate::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
   9 
  10 /// Run `f`, converting a panic into `Err(Diagnostic)` tagged with `label`
  11 /// instead of letting it unwind past this call site.
  12 ///
  13 /// Wraps `f` in `AssertUnwindSafe` internally rather than requiring callers
  14 /// to prove unwind-safety themselves. This codebase's data (`SourceData`,
  15 /// `ComponentEntry`, plugin state) has no interior mutability (`Cell`,
  16 /// `RefCell`) that could leave a torn, observable half-write behind after a
  17 /// caught panic — the whole operation is abandoned and its output discarded
  18 /// (or its `&mut` target left exactly as it was before the panicking call),
  19 /// so the invariant `AssertUnwindSafe` exists to protect doesn't apply here.
  20 pub fn contain_panic<T>(label: &str, f: impl FnOnce() -> T) -> Result<T, Diagnostic> {
  21     match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
  22         Ok(value) => Ok(value),
  23         Err(payload) => Err(Diagnostic {
  24             severity: DiagnosticSeverity::Error,
  25             message: format!("{label} panicked: {}", panic_message(payload.as_ref())),
  26             file: None,
  27             line: None,
  28             column: None,
  29             help: Some("This is an internal bug — please file a report with the input that triggered it.".into()),
  30             code: DiagnosticCode::InternalPanic,
  31         }),
  32     }
  33 }
  34 
  35 /// Extract a human-readable message from a `catch_unwind` payload — panics
  36 /// carry either a `&str` (`panic!("literal")`) or a `String`
  37 /// (`panic!("{}", x)`); anything else has no stable text representation.
  38 fn panic_message(payload: &(dyn std::any::Any + Send)) -> String {
  39     if let Some(s) = payload.downcast_ref::<&str>() {
  40         (*s).to_string()
  41     } else if let Some(s) = payload.downcast_ref::<String>() {
  42         s.clone()
  43     } else {
  44         "unknown panic payload".to_string()
  45     }
  46 }
  47 
  48 #[cfg(test)]
  49 mod tests {
  50     use super::*;
  51     use crate::types::DiagnosticCode;
  52 
  53     #[test]
  54     fn contain_panic_returns_ok_when_f_does_not_panic() {
  55         let result = contain_panic("test", || 42);
  56         assert_eq!(result, Ok(42));
  57     }
  58 
  59     #[test]
  60     fn contain_panic_converts_str_panic_to_diagnostic() {
  61         let result: Result<(), Diagnostic> = contain_panic("resolve:Button", || panic!("boom"));
  62         let diagnostic = result.expect_err("panic should be caught, not propagated");
  63         assert_eq!(diagnostic.code, DiagnosticCode::InternalPanic);
  64         assert!(
  65             diagnostic.message.contains("resolve:Button"),
  66             "message should carry the label, got {}",
  67             diagnostic.message
  68         );
  69         assert!(diagnostic.message.contains("boom"), "message should carry the panic text, got {}", diagnostic.message);
  70     }
  71 
  72     #[test]
  73     fn contain_panic_converts_string_panic_to_diagnostic() {
  74         let result: Result<(), Diagnostic> = contain_panic("parse:foo.tsx", || panic!("bad input: {}", 42));
  75         let diagnostic = result.expect_err("panic should be caught, not propagated");
  76         assert!(diagnostic.message.contains("bad input: 42"), "got {}", diagnostic.message);
  77     }
  78 }
