// ─── Entry Point ─────────────────────────────────────────────────────────────

/// Resolve a `ComponentMapping` to a complete `ComponentEntry`.
///
/// Called in parallel via rayon — must be `Send + Sync` (all data is owned/Arc'd).
pub fn resolve_component(mapping: &ComponentMapping, ctx: &ResolutionContext) -> (ComponentEntry, Vec<Diagnostic>) {
    let mut state = ResolveState::default();

    let chain = chain::resolve_props_chain(
        mapping.props_type_name.as_str(),
        &mapping.props_type_args,
        &mapping.file_path,
        mapping,
        ctx,
        &mut state,
        0,
    );

    // Build props BTreeMap — own props win over inherited props with same name.
    let mut props: BTreeMap<String, ParsedProp> = BTreeMap::new();
    for prop in chain.props {
        props.entry(prop.name.clone()).or_insert(prop);
    }

    // Populate notable_inherited from HTML element layers and non-HTML inherited layers.
    let mut notable_inherited: BTreeMap<String, ParsedProp> = BTreeMap::new();
    for layer in &chain.inheritance {
        if let Some(ref element) = layer.html_element {
            // Curated-mode synthesis only: Full mode already merged the real
            // attributes directly into `props` (see resolver/extends.rs); None
            // mode wants no HTML attrs synthesized at all.
            if ctx.html_attributes != crate::pipeline::HtmlAttributeMode::Curated {
                continue;
            }
            let notable_attrs = react_types::notable_html_attrs(element);
            for attr_name in notable_attrs {
                if props.contains_key(*attr_name) {
                    continue;
                } // own prop wins
                if notable_inherited.contains_key(*attr_name) {
                    continue;
                } // already added

                // Synthesize a minimal prop for display purposes
                let prop_type = html::infer_html_attr_prop_type(attr_name);
                notable_inherited.insert(
                    attr_name.to_string(),
                    ParsedProp::new(
                        attr_name.to_string(),
                        prop_type,
                        false,
                        None,
                        String::new(),
                        Default::default(),
                        Some(PropParent {
                            name: format!("{}HTMLAttributes", html::capitalize_element(element)),
                            file_name: "node_modules/@types/react/index.d.ts".to_string(),
                        }),
                        vec![],
                    ),
                );
            }
        } else {
            // For non-HTML layers: add inherited props from chain.inherited_by_name
            for (name, prop) in &chain.inherited_by_name {
                if !props.contains_key(name) && !notable_inherited.contains_key(name) {
                    notable_inherited.insert(name.clone(), prop.clone());
                }
            }
        }
    }

    // Detect discriminated union if applicable.
    let discriminant_prop = chain.discriminant_prop;

    (
        ComponentEntry {
            display_name: mapping.component_name.clone(),
            file_path: mapping.file_path.clone(),
            description: mapping.description.clone(),
            props,
            inheritance: chain.inheritance,
            notable_inherited,
            discriminant_prop,
            composes: chain.composes,
            tags: mapping.tags.clone(),
            methods: vec![],
        },
        state.diagnostics,
    )
}

// ─── Intermediate Resolution Result ──────────────────────────────────────────

/// Result of resolving a props chain (including extends).
struct ResolvedChain {
    /// Resolved props (may include inherited props).
    props: Vec<ParsedProp>,
    /// Inheritance layers, outermost first.
    inheritance: Vec<InheritedLayer>,
    /// Inherited props keyed by name — for notable_inherited population.
    inherited_by_name: FxHashMap<String, ParsedProp>,
    /// Type names that could not be resolved.
    composes: Vec<String>,
    /// Discriminant prop name if this is a discriminated union.
    discriminant_prop: Option<String>,
}

impl ResolvedChain {
    /// The base empty chain. Deliberately not `Default` — every accumulator
    /// site (`resolve_interface_chain`, `resolve_base_as_chain`, ...) that
    #[allow(clippy::new_ret_no_self)]
    pub(crate) fn new(raw: impl Into<std::string::String>, reason: OpaqueReason) -> PropType {
        PropType::Opaque(OpaqueDetail { raw: raw.into(), reason })
    }

    /// The sanctioned "give up and record why" constructor — pushes
    /// `diagnostic` onto `state` before building the value, so a resolver
    /// call site that reaches for this can't forget to explain the
    /// degradation the way the old bare `PropType::Opaque { .. }` literal let
    /// call sites do.
    pub(crate) fn give_up(
        state: &mut ResolveState,
        raw: impl Into<std::string::String>,
        reason: OpaqueReason,
        diagnostic: Diagnostic,
    ) -> PropType {
        state.diagnostics.push(diagnostic);
        Self::new(raw, reason)
    }

    pub(crate) fn raw(&self) -> &str {
        &self.raw
    }

    pub(crate) fn reason(&self) -> &OpaqueReason {
        &self.reason
    }
}

impl PropType {
    /// True if this type is a pure literal union (all members are literals).
    /// Used by serializers to choose between "enum" and "union" in RDT output.
    /// Requires at least 2 members — a 0- or 1-member "union" isn't a
    /// meaningful `<select>` shape, so RDT output falls back to plain
    /// `raw_string()` for those instead of an empty/single-option enum.
    pub fn is_literal_union(&self) -> bool {
        match self {
            PropType::Union(members) => {
                members.len() >= 2
                    && members.iter().all(|m| {
                        matches!(m, PropType::StringLiteral(_) | PropType::NumberLiteral(_) | PropType::BoolLiteral(_))
                    })
            }
                .map(|f| ObjectField {
                    name: f.name.clone(),
                    prop_type: resolve_collected_type(&f.collected_type, consuming_file, ctx, state, depth + 1),
                    required: f.required,
                    description: f.description.clone(),
                })
                .collect(),
        ),

        // ── Named type reference ──────────────────────────────────────────────
        CollectedType::Named { name, args } => resolve_named(name, args, consuming_file, ctx, state, depth),

        // ── typeof X ─────────────────────────────────────────────────────────
        CollectedType::TypeOf(name) => resolve_typeof(name, consuming_file, ctx, &mut state.diagnostics),

        // ── keyof X — only meaningful as Omit's key argument (handled structurally
        // there, see resolver/alias.rs); standalone usage needs a general
        // type-to-key-names resolver we don't have, so degrade gracefully.
        CollectedType::KeyOf(_) => {
            let diag = opaque_diagnostic("a standalone 'keyof'", ct, consuming_file);
            OpaqueDetail::give_up(state, ct.to_raw_string(), OpaqueReason::MappedType, diag)
        }

        // ── Generic-alias substitution marker — switch file context to where
        // `inner` was actually written (see the `CollectedType::AtFile` doc
        // comment) and continue resolving from there.
        CollectedType::AtFile { file, inner } => resolve_collected_type(inner, file, ctx, state, depth),

        // ── Indexed access ───────────────────────────────────────────────────
        CollectedType::IndexedAccess { obj, key } => {
            resolve_indexed_access(obj, key, consuming_file, ctx, state, depth)
        }

        // ── Template literal ─────────────────────────────────────────────────
        CollectedType::TemplateLiteral(parts) => resolve_template_literal(parts, consuming_file, ctx, state, depth),

        // ── Function type ─────────────────────────────────────────────────────
        CollectedType::Function { params, param_names, return_type } => {
            resolve_function_type(params, param_names, return_type, consuming_file, ctx, state, depth)
        }

        // ── Opaque (needs type checker) ───────────────────────────────────────
        CollectedType::Conditional { .. } => {
            let diag = opaque_diagnostic("a conditional type", ct, consuming_file);
            OpaqueDetail::give_up(state, ct.to_raw_string(), OpaqueReason::ConditionalType, diag)
        }
        CollectedType::Mapped { .. } => {
            let diag = opaque_diagnostic("a mapped type", ct, consuming_file);
            OpaqueDetail::give_up(state, ct.to_raw_string(), OpaqueReason::MappedType, diag)
        }

//! Union, intersection, and indexed access resolution.

use camino::Utf8Path;

