            // `true` would make a client's hover request, which carries an
            // `id`, hang forever waiting for a response that never comes.
            "hoverProvider": false
        },
        "serverInfo": {
            "name": "oxc-react-docgen-lsp",
            "version": env!("CARGO_PKG_VERSION")
        }
    })
}

